(()=>{
 'use strict';
 const S=Site,C=Cimora,E=S.esc,P=PointsModel;
 const amount=n=>Number(n).toLocaleString('zh-CN')+' 积分',kind=k=>({market:'资产包',unlock:'章节解锁',support:'读者支持',topup:'充值',income:'创作收益'}[k]||'积分变动');
 const button=(title,act,id='')=>`<button type="button" class="cm-button ghost" data-pw="${act}" data-id="${E(id)}">${title}</button>`;
 const link=(title,url)=>C.link(title,url,'cm-button ghost');
 function ensure(meta){if(!meta.points)meta.points=P.initial(C.M.db.wallet);if(meta.points.version!==1)throw Error('积分钱包版本无法读取，请保留本机记录。');return meta.points;}
 function read(){return ensure(StudioLibrary.meta());}
 function change(fn){StudioLibrary.guard();return StudioLibrary.changeMeta(meta=>fn(ensure(meta),meta));}
 const balance=()=>P.balance(read()),orders=()=>read().orders.filter(o=>o.status==='paid');
 function loadHistory(){const state=window.CommunityStudio?.status();if(state&&!state.loaded&&!state.loading&&!state.failure)void CommunityStudio.refresh().then(()=>{if(['settings','wallet'].includes(S.context?.parts[1]))S.render();});}
 const entitled=(workId,chapterId)=>orders().some(o=>o.kind==='unlock'&&o.workId===workId&&o.chapterId===chapterId);
 function target(o){return o.kind==='market'?'/app/market/'+encodeURIComponent(o.productId)+'?delivery=1':'/app/community/'+encodeURIComponent(o.workId)+'?chapter='+encodeURIComponent(o.chapterId||'');}
 function legacy(type='all'){loadHistory();const market=(window.MarketStudio?.read().orders||[]).filter(o=>o.currency!=='points'&&['all','market'].includes(type)),community=(window.CommunityStudio?.history?.()||[]).filter(o=>type==='all'||o.type===type);return `<details class="cm-panel sa-form pw-history"><summary>历史记录 · 保留原币种</summary><p>旧订单保留原币种与权益，按当前购买分类展示。</p>${market.map(o=>`<article class="pw-row"><div><strong>${E(o.title)} · 旧市场订单</strong>${link('查看历史交付','/app/market/'+encodeURIComponent(o.productId))}</div><b>¥${Number(o.amount).toFixed(2)}</b></article>`).join('')}${community.map(o=>`<article class="pw-row"><div><strong>${E(o.title)} · ${kind(o.type)}</strong>${link('查看作品','/app/community/'+encodeURIComponent(o.workId)+'?chapter='+encodeURIComponent(o.chapterId||''))}</div><b>¥${(o.amount/100).toFixed(2)}</b></article>`).join('')}${!market.length&&!community.length?'<p>暂无旧人民币订单。</p>':''}<p>历史资源购买 ${C.M.db.purchases.length} 项；旧流水 ${C.M.db.ledger.length} 条。原有演示积分余额仅首次沿用，不重复发放。</p>${(type==='all'?C.M.db.ledger:[]).map(l=>`<article class="pw-row"><span>${E(l.title)} · 原有积分流水</span><b>${l.delta>0?'+':''}${amount(l.delta)}</b></article>`).join('')}</details>`;}
 function purchases(){const type=S.context.params.get('type')||'all',filters=[['all','全部'],['market','资产包'],['unlock','章节解锁'],['support','支持记录']],selected=filters.some(([id])=>id===type)?type:'all',rows=read().orders.filter(o=>selected==='all'||o.kind===selected);return `<section class="cm-panel sa-form" id="pw-purchases"><h2>我的购买</h2><p>资产包保留交付快照，章节保留阅读权限；支持作者不包含解锁或素材许可。</p><nav class="pw-purchase-filters" aria-label="购买记录分类">${filters.map(([id,title])=>`<a href="#/app/settings?tab=purchases&type=${id}" aria-current="${selected===id?'page':'false'}">${title}</a>`).join('')}</nav>${rows.map(o=>`<article class="pw-row mk-order-row"><div><strong>${E(o.title)}</strong><small>${kind(o.kind)}${o.chapterTitle?' · '+E(o.chapterTitle):''} · ${new Date(o.at).toLocaleString('zh-CN')} · ${o.status==='paid'?'已完成':'已退款'}</small></div><div><b>${amount(o.amount)}</b>${o.status==='paid'?link(o.kind==='market'?'查看交付':o.kind==='unlock'?'继续阅读':'查看作品',target(o)):''}</div></article>`).join('')||'<p>暂无'+(selected==='all'?'购买':kind(selected))+'记录。可以先浏览市场或作品广场。</p>'}<div class="sa-actions">${link('逛创作市场','/app/market')}${link('去作品广场','/app/community')}</div></section>${legacy(selected)}`;}
 function wallet(){const s=read();return `<section class="cm-panel sa-form" id="pw-wallet"><div class="sa-heading"><div><h2>积分钱包</h2><p>创作市场与作品广场共用，同一余额、同一本流水。</p></div>${button('演示充值','topup')}</div><div class="pw-stats"><section><small>可消费余额</small><strong data-pw-balance>${amount(P.balance(s))}</strong></section><section><small>充值与原有积分</small><strong>${amount(s.purchased)}</strong><small>仅用于消费，不可提现</small></section><section><small>已转入钱包的收益</small><strong>${amount(s.earned)}</strong><small>已包含在可消费余额中；消费后相应收益减少</small></section></div><p class="sa-note">生成额度用于创作任务，独立于此钱包。充值、交易和收益均为本机模拟，不发生真实付款或到账。</p><div class="sa-actions">${link('查看我的购买','/app/settings?tab=purchases')}${link('收益结算与提现','/app/creator?tab=income')}</div></section><section class="cm-panel sa-form"><h2>积分流水</h2>${s.ledger.map(l=>`<article class="pw-row"><div><strong>${E(l.title)}</strong><small>${new Date(l.at).toLocaleString('zh-CN')}${l.example?' · 收益样例':''}</small></div><b>${l.delta>0?'+':''}${amount(l.delta)}${l.kind==='withdraw'?'（钱包变动）':''}</b></article>`).join('')||'<p>暂无新流水。首次消费将沿用原有演示余额，历史记录保留。</p>'}</section><p class="sa-note">历史购买与原有积分记录可在「我的购买」查看。</p>`;}
 function income(){const s=read(),sum=P.incomeSummary(s),month=AccountUsage.day(new Date()).slice(0,7),net=s.incomes.filter(i=>i.status!=='refunded'&&AccountUsage.day(new Date(i.at)).slice(0,7)===month).reduce((n,i)=>n+i.net,0);return `<p class="sa-note">创作收益本机演示 · 自己的消费不会成为自己的收入。收益样例模拟其他买家的订单，均有明确标记；尚未接入真实结算与提现。</p><div class="pw-stats"><section><small>本月净收入（含样例）</small><strong>${amount(net)}</strong></section><section><small>待结算</small><strong>${amount(sum.pending)}</strong></section><section><small>已结算可用收益</small><strong>${amount(sum.withdrawable)}</strong><small>尚未转入钱包 ${amount(sum.settled)} · 已转入钱包 ${amount(s.earned)}</small></section><section><small>提现申请中</small><strong>${amount(sum.frozen)}</strong></section></div><section class="cm-panel sa-form"><div class="sa-heading"><div><h2>收益来源与结算</h2><p>章节解锁、读者支持与资产包交易统一以积分入账。平台费率和兑换比例待确定，样例服务费为 0。</p></div>${button('载入收益演示','income-demo')}</div><div class="sa-actions pw-income-actions">${sum.pending?button('模拟全部结算','settle-all'):''}${sum.settled?button('全部转入钱包','transfer-all'):''}${button('申请演示提现','withdraw')}${link('查看积分钱包','/app/settings?tab=wallet')}</div>${['unlock','support','market'].map(k=>`<p>${k==='market'?'资产包收入':'作品收入 · '+kind(k)}：${amount(s.incomes.filter(i=>i.kind===k&&i.status!=='refunded').reduce((n,i)=>n+i.net,0))}</p>`).join('')}${s.incomes.map(i=>`<article class="pw-row"><div><strong>${E(i.title)}${i.example?' · 收益样例':''}</strong><small>${kind(i.kind)} · 订单 ${E(i.id)}<br>收入 ${amount(i.gross)} − 服务费 ${amount(i.fee)} = 净收入 ${amount(i.net)}<br>${i.status==='pending'?'待结算':i.status==='refunded'?'已冲正':'已结算 · 尚未转入钱包 '+amount(i.available)}</small></div><b>${amount(i.net)}</b></article>`).join('')||'<p>暂无收入。发布作品或上架资产包不会自动生成收益。</p>'}<p class="sa-note">结算完成后可汇总转入钱包消费，或申请提现；转入钱包是同笔收益的位置变化，不会产生第二份收入。正式结算由后台按周期执行。申请将冻结收益，不能同时用于消费；充值积分不可提现。此处只演示积分申请，不计算法币金额。</p></section><section class="cm-panel sa-form"><h2>提现申请</h2>${s.withdrawals.map(w=>`<article class="pw-row"><div><strong>${amount(w.amount)} · ${w.status==='pending'?'申请中，已冻结':'已取消，已解冻'}</strong><small>${new Date(w.at).toLocaleString('zh-CN')} · 本机演示，没有真实到账</small></div>${w.status==='pending'?button('取消申请','cancel-withdraw',w.id):''}</article>`).join('')||'<p>暂无申请。</p>'}</section>`;}
 async function demo(){await change(s=>{for(const [id,k,title,n]of [['chapter','unlock','示例连载 · 章节解锁',40],['reader','support','示例连载 · 读者支持',50],['asset','market','都市角色包 · 资产销售',180]])P.addIncome(s,{id:'income-demo-'+id,kind:k,title,gross:n,example:true});});}
 let busy=false;
 document.addEventListener('click',async event=>{
  const node=event.target.closest('[data-pw]');if(!node)return;event.preventDefault();if(busy)return;const act=node.dataset.pw,id=node.dataset.id;
  try{
   if(['topup','withdraw'].includes(act)){const withdraw=act==='withdraw';S.modal(withdraw?'申请演示提现':'演示充值',`<form class="sa-form" id="pw-form"><p>${withdraw?'仅可使用已结算创作收益；提交后冻结，取消后解冻。':'充值积分可购买资产、解锁章节或支持作者，不可提现。'}</p><label>${withdraw?'申请积分':'充值积分'}<input id="pw-amount" type="number" min="1" step="1" required value="${withdraw?Math.min(100,P.incomeSummary(read()).withdrawable)||1:500}"></label><p>本机模拟，不发生真实付款、到账或提现。正式兑换比例与费用尚未设定。</p><p id="pw-error" role="alert"></p></form>`,button(withdraw?'确认演示申请':'确认演示充值',withdraw?'confirm-withdraw':'confirm-topup',crypto.randomUUID()));return;}
   busy=true;node.disabled=true;
   if(act==='income-demo')await demo();
   else if(act==='settle')await change(s=>P.settle(s,id));
   else if(act==='settle-all')await change(s=>{for(const income of s.incomes)if(income.status==='pending')P.settle(s,income.id);});
   else if(act==='transfer-all')await change(s=>{for(const income of s.incomes)if(income.status==='settled'&&income.available)P.transfer(s,income.id);});
   else if(act==='transfer')await change(s=>P.transfer(s,id));
   else if(act==='cancel-withdraw')await change(s=>P.cancelWithdrawal(s,id));
   else if(act==='confirm-topup'||act==='confirm-withdraw'){const form=document.getElementById('pw-form');if(!form.reportValidity())return;const n=Number(document.getElementById('pw-amount').value);await change(s=>act==='confirm-topup'?P.topup(s,n,id):P.withdraw(s,n,id));S.close();}
   S.render();S.toast('演示记录已保存');
  }catch(error){const out=document.getElementById('pw-error');if(out)out.textContent=error.message;else S.toast(error.message);}finally{busy=false;if(node.isConnected)node.disabled=false;}
 });
 window.addEventListener('storage',event=>{if(event.key===StudioLibrary.KEY)void StudioManagementStorage.reload().then(()=>S.render());});
 window.addEventListener('focus',()=>{void StudioManagementStorage.reload().then(()=>{if(['settings','wallet','creator','community','market'].includes(S.context?.parts[1]))S.render();});});
 window.PointsWallet={ensure,read,change,balance,orders,entitled,wallet,purchases,income,demo,loadHistory};
})();
